}

function identifyPrimaryFailure(scorecard){
  const criteria=['pattern','code','tests','complexity','communication'];
  let lowest=criteria[0];
  for(const c of criteria){
    if(scorecard[c]<scorecard[lowest])lowest=c;
  }
  return lowest;
}

