// DEBRIEF AND TARGETED FIX FRAMEWORK

// STEP 1: Gap Analysis — compile scorecard data from all 3 simulations
function analyzeGaps(scorecards) {
    const criteria = ['pattern', 'code', 'tests', 'complexity', 'communication'];
    const avgScores = {};
    for (const criterion of criteria) {
        const scores = scorecards.flatMap(sc =>
            [sc.easy?.[criterion] || 0, sc.medium?.[criterion] || 0,
             sc.p1?.[criterion] || 0, sc.p2?.[criterion] || 0,
             sc.hardProblem?.[criterion] || 0]
            .filter(s => s > 0) // only count scored criteria
        );
        avgScores[criterion] = scores.reduce((a,b)=>a+b,0) / (scores.length || 1);
    }
    // Sort by lowest average to identify primary gap
    return Object.entries(avgScores)
        .sort(([,a],[,b]) => a-b)
        .map(([k,v]) => ({ criterion: k, avgScore: v.toFixed(2) }));
}

// STEP 2: Targeted Fix Protocol
const targetedFixes = {
    pattern: {
        diagnosis: 'Archetype misidentification or > 5 min to identify',
        fix: [
            'Re-read Module 10 L4 archetype taxonomy (5 types)',
            'Do 10 x 60-second archetype identification drills (read only, no coding)',
            'Complete Module 10 L6 mini-challenge: 5 transfer exercises',
        ],
        timeline: '3 days',
        verificationTest: 'Identify archetypes for 10 random hard problems in < 2 min each'
    },
    code: {
        diagnosis: 'Correct pattern, buggy or incomplete implementation',
        fix: [
            'Identify which algorithm family fails (e.g., interval DP transitions)',
            'Re-read the specific module section',
            'Implement 5 problems from that family from scratch without hints',
        ],
        timeline: '3-5 days per family',
        verificationTest: 'Implement same algorithm twice (3 days apart) without errors'
    },
    communication: {
        diagnosis: 'Silences > 30-90s, complexity not stated unprompted',
        fix: [
            'Module 14 L2 Communication Drill (L2-M14 Lesson 5)',
            '5 x 15-min verbal narration sessions on solved problems',
            '30-second no-silence phone alarm drill',
        ],
        timeline: '5 days',
        verificationTest: 'T_verbal / T_silent ratio < 1.3 on 3 consecutive problems'
    },
    tests: {
        diagnosis: 'Provided examples pass, edge cases fail',
        fix: [
            'For 10 problems: write 3 edge cases BEFORE solving',
            'Edge case checklist: n=0, n=1, all same, negative, max n',
            'Add edge case testing to Step 8 explicitly',
        ],
        timeline: '3 days',
        verificationTest: 'Zero edge case failures in 5 consecutive problems'
    },
};

// STEP 3: Verification Simulation
// After running the fix: one additional simulation session
// Pass criterion: the previously failing criterion now scores 4+ consistently
